import csv, math
from datetime import datetime
p='/archive/payment_batch_export_FcLmGvW4bc.tsv'
rows=[]
with open(p,newline='') as f:
    r=csv.DictReader(f, delimiter='\t')
    for row in r:
        rows.append(row)

def dist(a,b,c,d):
    return ((a-c)**2 + (b-d)**2) ** 0.5

def t(s):
    return datetime.fromisoformat(s.replace('Z','+00:00'))

fraud=set()
# strong pattern 1: same device used by >=3 customers
from collections import defaultdict
by_dev=defaultdict(set)
for row in rows:
    by_dev[row['device_fingerprint']].add(row['customer_ref'])
strong_devs={d for d,c in by_dev.items() if len(c)>=3}
for row in rows:
    if row['device_fingerprint'] in strong_devs:
        fraud.add(row['row_id'])

# strong pattern 2: same payment method used by >=3 customers
by_pm=defaultdict(set)
for row in rows:
    by_pm[row['payment_method_fingerprint']].add(row['customer_ref'])
strong_pms={d for d,c in by_pm.items() if len(c)>=3}
for row in rows:
    if row['payment_method_fingerprint'] in strong_pms:
        fraud.add(row['row_id'])

# strong pattern 3: impossible travel clusters per customer (transitive within 30m and different stores, far distance)
by_cust=defaultdict(list)
for i,row in enumerate(rows):
